import { Button, Navigation, NavigationStack, RealityView, Script, Text, VStack, useRef, useState } from "scripting"

type ClipPlayer = { model: RealityKit.Entity; clip: RealityKit.AnimationClip }

function RetargetDemo({ renderer, source, target }: {
  renderer: RealityKit.Renderer
  source: ClipPlayer
  target: ClipPlayer
}) {
  const [status, setStatus] = useState("Ready")
  const players = useRef<RealityKit.AnimationPlayback[]>([])
  function stop() {
    for (const player of players.current) player.dispose()
    players.current = []
  }
  function showMotion(at?: number) {
    try {
      stop()
      for (const { model, clip } of [source, target]) {
        const player = model.playAnimation(clip, { startsPaused: at !== undefined })
        players.current.push(player)
        if (at !== undefined) player.seek(at)
      }
      setStatus(at === undefined ? "Playing source and target" : "Showing the same instant on both characters")
    } catch (error) {
      stop()
      setStatus(String(error))
    }
  }
  return <NavigationStack>
    <VStack spacing={12} padding navigationTitle="Skeletal retargeting">
      <Text>Left · Aster source  /  Right · Juniper target</Text>
      <RealityView renderer={renderer} frame={{ height: 280 }} accessibilityHidden />
      <Text>{status}</Text>
      <Button title="Play both characters" action={() => showMotion()} />
      <Button title="Show the raised-arm pose" action={() => showMotion(1.5)} />
      <Button title="Stop both characters" action={() => {
        stop()
        setStatus("Stopped")
      }} />
    </VStack>
  </NavigationStack>
}

function modelWithSkeleton(entity: RealityKit.Entity): RealityKit.Entity | undefined {
  if (entity.skeletons().length > 0) return entity
  for (const child of entity.info.children) {
    const model = modelWithSkeleton(child)
    if (model) return model
  }
}

async function loadFixture(folder: string, name: string, encoded: string) {
  const compressed = Data.fromBase64String(encoded)
  if (!compressed) throw Error("The embedded character asset is missing.")
  const path = folder + "/" + name + ".usda"
  await FileManager.writeAsData(path, compressed.decompressed(CompressionAlgorithm.lzfse))
  return RealityKit.Entity.load(path, { trustExternalReferences: true })
}

async function run() {
  let folder: string | undefined
  try {
    if (!RealityKit.getCapabilities().skeletalRetargeting) {
      await Dialog.alert({ message: "Skeletal retargeting requires iOS 27 or later in the foreground app." })
      return
    }
    const path = FileManager.temporaryDirectory + "/RealityRetarget-" + UUID.string()
    await FileManager.createDirectory(path)
    folder = path
    const original = await loadFixture(path, "Aster", aster)
    const destination = await loadFixture(path, "Juniper", juniper)
    const source = original.animations({ recursive: true }).find(entry => entry.clip.info.sampledSkeletal)
    const targetModel = modelWithSkeleton(destination)
    if (!source || !targetModel) throw Error("RealityKit did not import the sampled clip or target skeleton.")
    const sourceRig = RealityKit.SkeletonResource.fromEntity(source.owner)
    const targetRig = RealityKit.SkeletonResource.fromEntity(targetModel)
    const configuration = RealityKit.RetargetingConfiguration.automatchBiped(sourceRig, targetRig)
    const transferred = source.clip.processSkeletal({ name: "Juniper motion", retargeting: configuration })
    sourceRig.dispose()
    targetRig.dispose()
    configuration.dispose()

    original.setTransform({ position: [-1.05, 0, 0] })
    destination.setTransform({ position: [1.05, 0, 0] })
    const scene = RealityKit.Scene.create()
    scene.add(original)
    scene.add(destination)
    const renderer = RealityKit.Renderer.create(scene, {
      camera: { projection: "orthographic", position: [0, 1.0, 5], target: [0, 1.0, 0], scale: 4.6 },
      background: [0.11, 0.13, 0.18, 1],
    })
    await Navigation.present({ element: <RetargetDemo renderer={renderer}
      source={{ model: source.owner, clip: source.clip }} target={{ model: targetModel, clip: transferred }} /> })
  } catch (error) {
    console.error(String(error))
    await Dialog.alert({ title: "Retargeting demo", message: String(error) })
  } finally {
    if (folder) {
      try { await FileManager.remove(folder) } catch (error) { console.log(String(error)) }
    }
    Script.exit()
  }
}

